def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    marker = next(x for x in Counter(x for row in grid for x in row) if x != background)
    out = [row[:] for row in grid]

    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(marks, marks[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3

    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(marks, marks[1:]):
            for arow in range(a + 1, b):
                out[arow][c] = 3

    return out
